-- =====================================================================
-- trip-assistant — tables, indexes, trigger, and Row Level Security
-- Run in: Supabase Dashboard → SQL Editor → New query → paste → Run.
-- Safe to re-run (uses IF NOT EXISTS / OR REPLACE / DROP ... IF EXISTS).
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------

-- One row per conversation. The id is generated by the browser (UUID)
-- so the page can navigate to /trip-assistant/<id> immediately.
create table if not exists public.assistant_conversations (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid()
                references auth.users (id) on delete cascade,
  title       text not null check (char_length(title) between 1 and 200),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- Every question (role = 'user') and AI answer (role = 'assistant').
-- user rows use `content`; assistant rows use `answer` (JSON, format in docs/plan.md §5).
create table if not exists public.assistant_messages (
  id               uuid primary key default gen_random_uuid(),
  conversation_id  uuid not null
                     references public.assistant_conversations (id) on delete cascade,
  role             text not null check (role in ('user', 'assistant')),
  content          text check (content is null or char_length(content) <= 4000),
  answer           jsonb,
  created_at       timestamptz not null default now(),
  constraint assistant_messages_shape check (
    (role = 'user'      and content is not null and answer is null) or
    (role = 'assistant' and answer  is not null)
  )
);

-- ---------------------------------------------------------------------
-- 2. Indexes
-- ---------------------------------------------------------------------

-- Sidebar: a user's conversations, newest first.
create index if not exists assistant_conversations_user_updated_idx
  on public.assistant_conversations (user_id, updated_at desc);

-- Conversation page: messages in order.
create index if not exists assistant_messages_conversation_created_idx
  on public.assistant_messages (conversation_id, created_at);

-- ---------------------------------------------------------------------
-- 3. Keep updated_at fresh: a new message moves its conversation to the top.
-- ---------------------------------------------------------------------

create or replace function public.assistant_touch_conversation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.assistant_conversations
     set updated_at = now()
   where id = new.conversation_id;
  return new;
end;
$$;

drop trigger if exists assistant_messages_touch_conversation on public.assistant_messages;
create trigger assistant_messages_touch_conversation
  after insert on public.assistant_messages
  for each row execute function public.assistant_touch_conversation();

-- ---------------------------------------------------------------------
-- 4. Access: only signed-in users, never anonymous visitors.
-- ---------------------------------------------------------------------

revoke all on public.assistant_conversations from anon;
revoke all on public.assistant_messages      from anon;

grant select, insert, update, delete on public.assistant_conversations to authenticated;
grant select, insert, delete         on public.assistant_messages      to authenticated;

-- ---------------------------------------------------------------------
-- 5. Row Level Security: each user sees and changes only their own data.
-- ---------------------------------------------------------------------

alter table public.assistant_conversations enable row level security;
alter table public.assistant_messages      enable row level security;

-- Conversations ---------------------------------------------------------
drop policy if exists "Own conversations: select" on public.assistant_conversations;
create policy "Own conversations: select"
  on public.assistant_conversations for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "Own conversations: insert" on public.assistant_conversations;
create policy "Own conversations: insert"
  on public.assistant_conversations for insert to authenticated
  with check (user_id = (select auth.uid()));

drop policy if exists "Own conversations: update" on public.assistant_conversations;
create policy "Own conversations: update"
  on public.assistant_conversations for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists "Own conversations: delete" on public.assistant_conversations;
create policy "Own conversations: delete"
  on public.assistant_conversations for delete to authenticated
  using (user_id = (select auth.uid()));

-- Messages (allowed when the parent conversation belongs to the user) ----
drop policy if exists "Own messages: select" on public.assistant_messages;
create policy "Own messages: select"
  on public.assistant_messages for select to authenticated
  using (exists (
    select 1 from public.assistant_conversations c
     where c.id = conversation_id and c.user_id = (select auth.uid())
  ));

drop policy if exists "Own messages: insert" on public.assistant_messages;
create policy "Own messages: insert"
  on public.assistant_messages for insert to authenticated
  with check (exists (
    select 1 from public.assistant_conversations c
     where c.id = conversation_id and c.user_id = (select auth.uid())
  ));

drop policy if exists "Own messages: delete" on public.assistant_messages;
create policy "Own messages: delete"
  on public.assistant_messages for delete to authenticated
  using (exists (
    select 1 from public.assistant_conversations c
     where c.id = conversation_id and c.user_id = (select auth.uid())
  ));

-- ---------------------------------------------------------------------
